evidence.command:
rm -rf /tmp/p39c/lib1 && mkdir -p /tmp/p39c/lib1/d1 /tmp/p39c/lib1/d2 && cd /tmp/p39c/lib1
cat > greetlib.ct <<'EOF'
#include <stdio.h>

pub trait Greeter {
    void greet();
}

pub struct Person {
    char *name;
} use Greeter;

impl Greeter for Person {
    void greet() { printf("hi %s\n", self->name); }
}

static Person ps[2];

pub void run_lib(void)
{
    ps[0].name = "A";
    ps[1].name = "B";
    ps[0].greet();
    ps[1].greet();
}
EOF
/tmp/p39head/ct greetlib.ct -o greetlib.c
sed 's/^void run_lib(void) {/__attribute__((visibility("default"))) void run_lib(void) {/' greetlib.c > greetlib_attr.c
cc -std=c99 -fvisibility=hidden -c greetlib_attr.c -o greetlib_attr.o
printf '_run_lib\n' > exports.txt
cc -r -Wl,-exported_symbols_list,/tmp/p39c/lib1/exports.txt -o d1/sealed.o greetlib_attr.o 2>d1/stderr.txt; echo "cc -r #1 rc=$?"
sleep 2
cc -r -Wl,-exported_symbols_list,/tmp/p39c/lib1/exports.txt -o d2/sealed.o greetlib_attr.o 2>d2/stderr.txt; echo "cc -r #2 rc=$?"
echo '--- stderr #1'; cat d1/stderr.txt
ZERO_AR_DATE=1 ar rcs d1/libg.a d1/sealed.o
ZERO_AR_DATE=1 ar rcs d2/libg.a d2/sealed.o
echo '--- sha256'; shasum -a 256 d1/sealed.o d2/sealed.o d1/libg.a d2/libg.a
cmp d1/sealed.o d2/sealed.o && echo 'sealed IDENTICAL'
cmp d1/libg.a d2/libg.a && echo 'archive IDENTICAL'
echo '--- nm -g sealed'; nm -g --defined-only d1/sealed.o
echo '--- nm -m sealed'; nm -m d1/sealed.o | grep -E '_Person_Greeter_vtable|___ct_init|__mod_init_func|_run_lib'
echo '--- ar t'; ar t d1/libg.a
cat > cons.c <<'EOF'
void run_lib(void);
int main(void) { run_lib(); return 0; }
EOF
cc -std=c99 cons.c d1/libg.a -o consbin; echo "consumer link rc=$?"
./consbin; echo "consumer run rc=$?"

rm -rf /tmp/p39c/lib1h && mkdir -p /tmp/p39c/lib1h/hid && cd /tmp/p39c/lib1h
cat > greetlib.ct <<'EOF'
#include <stdio.h>

pub trait Greeter {
    void greet();
}

pub struct Person {
    char *name;
} use Greeter;

impl Greeter for Person {
    void greet() { printf("hi %s\n", self->name); }
}

static Person ps[2];

pub void run_lib(void)
{
    ps[0].name = "A";
    ps[1].name = "B";
    ps[0].greet();
    ps[1].greet();
}
EOF
/tmp/p39head/ct greetlib.ct -o greetlib.c
printf '_run_lib\n' > exports.txt
cc -std=c99 -fvisibility=hidden -c greetlib.c -o greetlib_hid.o
cc -r -Wl,-exported_symbols_list,/tmp/p39c/lib1h/exports.txt -o hid/sealed.o greetlib_hid.o 2>hid/stderr.txt; echo "cc -r rc=$?"
echo '--- nm -g sealed'; nm -g --defined-only hid/sealed.o; echo '(empty)'
echo '--- nm -m run_lib'; nm -m hid/sealed.o | grep _run_lib

rm -rf /tmp/p39c/ctor && mkdir /tmp/p39c/ctor && cd /tmp/p39c/ctor
cat > a.c <<'EOF'
#include <stdio.h>
__attribute__((constructor)) void a_init(void) { puts("A-init"); }
int a_fn(void) { return 1; }
EOF
cat > b.c <<'EOF'
#include <stdio.h>
__attribute__((constructor)) void b_init(void) { puts("B-init"); }
int b_fn(void) { return 2; }
EOF
cat > m.c <<'EOF'
int a_fn(void); int b_fn(void);
int main(void) { return a_fn() + b_fn() - 3; }
EOF
cc -c a.c b.c
printf '_a_fn\n_b_fn\n' > exports.txt
cc -r -Wl,-exported_symbols_list,/tmp/p39c/ctor/exports.txt -o sealed.o a.o b.o 2>stderr.txt; echo "cc -r rc=$?"
echo '--- stderr'; cat stderr.txt
echo '--- nm -g'; nm -g --defined-only sealed.o
echo '--- nm -m init'; nm -m sealed.o | grep -i init
cc m.c sealed.o -o mbin; echo "link rc=$?"
./mbin; echo "run rc=$?"

rm -rf /tmp/p39c/lib3 && mkdir -p /tmp/p39c/lib3/units && cd /tmp/p39c/lib3
cp /tmp/p39head/src/test/modules/split/shapes.h.ct /tmp/p39head/src/test/modules/split/impl_dog.h.ct .
cat > box.h.ct <<'EOF'
import shapes;
import impl_dog;

pub void via_vtable(void)
{
    Dog d = *dog_get();
    Speak s = d;
    s.hi();
}
EOF
/tmp/p39head/ct build --emit-c -I . box.h.ct --outdir units --cc true >/dev/null 2>&1
cd units && for c in *.c; do cc -std=c99 -I. -c "$c" -o "${c%.c}.o"; done; cd ..
echo '--- unit objects before seal'; ls units/*.o
echo '--- nm before seal'; nm -g --defined-only units/*.o
printf '_via_vtable\n_dog_get\n' > exports.txt
cc -r -Wl,-exported_symbols_list,/tmp/p39c/lib3/exports.txt -o units/sealed.o units/shapes.o units/impl_dog.o units/box.o 2>units/stderr.txt; echo "cc -r rc=$?"
echo '--- stderr'; cat units/stderr.txt
echo '--- unit objects after seal'; ls units/*.o
echo '--- nm unit box.o still works'; nm -u units/box.o
ZERO_AR_DATE=1 ar rcs lib3.a units/sealed.o
echo '--- ar t'; ar t lib3.a
echo '--- nm -g archive'; nm -g --defined-only lib3.a
cat > cons.c <<'EOF'
void via_vtable(void);
int main(void) { via_vtable(); return 0; }
EOF
cc -std=c99 cons.c lib3.a -o consbin; echo "consumer link rc=$?"
./consbin; echo "consumer run rc=$?"
